@ExtendWith(MockitoExtension.class)
class OrderCancellationTest {

    @Mock
    private InventoryService inventoryService;

    @Mock
    private ShippingService shippingService;

    @Mock
    private EmailService emailService;

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldNotProcessShippingWhenOrderIsCancelled() {
        var order = new Order(1L, "Laptop", OrderStatus.CANCELLED);

        orderService.handleOrder(order);

        // Verify shipping was never initiated
        verify(shippingService, never()).scheduleDelivery(any());
        verify(inventoryService, never()).decrementStock(anyString());
        // Verify email service had no interactions at all
        verifyNoInteractions(emailService);
    }
}
